158→  const [modalOpen, setModalOpen] = useState(false);
159→  const [editingRule, setEditingRule] = useState<Rule | null>(null);
160→
161→  // Form state
162→  const [name, setName] = useState("");
163→  const [zone, setZone] = useState("");
164→  const [zipCodes, setZipCodes] = useState("");
165→  const [minOrderAmount, setMinOrderAmount] = useState("");
166→  const [deliveryFee, setDeliveryFee] = useState("");
167→  const [freeShippingAbove, setFreeShippingAbove] = useState("");
168→  const [estimatedDays, setEstimatedDays] = useState("");
