217→
218→  const handleSave = useCallback(() => {
219→    const fd = new FormData();
220→    fd.set("intent", editingRule ? "update" : "create");
221→    if (editingRule) fd.set("id", editingRule.id);
222→    fd.set("name", name);
223→    fd.set("zone", zone);
224→    fd.set("zipCodes", zipCodes);
225→    fd.set("minOrderAmount", minOrderAmount);
226→    fd.set("deliveryFee", deliveryFee);
227→    fd.set("freeShippingAbove", freeShippingAbove);
228→    fd.set("estimatedDays", estimatedDays);
229→    fd.set("cutoffTime", cutoffTime);
230→    fd.set("daysOfWeek", selectedDays.join(","));
231→    fd.set("priority", priority);
232→    fetcher.submit(fd, { method: "POST" });
233→    setModalOpen(false);
234→    resetForm();
235→    shopify.toast.show(editingRule ? "Rule updated" : "Rule created");
236→  }, [
237→    editingRule,
238→    name,
239→    zone,
240→    zipCodes,
241→    minOrderAmount,
242→    deliveryFee,
243→    freeShippingAbove,
244→    estimatedDays,
245→    cutoffTime,
246→    selectedDays,
247→    priority,
248→    fetcher,
249→    resetForm,
250→    shopify,
251→  ]);
252→
253→  const handleDelete = useCallback(
254→    (id: string) => {
255→      const fd = new FormData();
256→      fd.set("intent", "delete");
257→      fd.set("id", id);
258→      fetcher.submit(fd, { method: "POST" });
259→      shopify.toast.show("Rule deleted");
260→    },
261→    [fetcher, shopify],
262→  );
263→
264→  const handleToggle = useCallback(
265→    (id: string, isActive: boolean) => {
266→      const fd = new FormData();
267→      fd.set("intent", "toggle");
268→      fd.set("id", id);
269→      fd.set("isActive", String(isActive));
270→      fetcher.submit(fd, { method: "POST" });
271→    },
272→    [fetcher],
273→  );
274→
275→  const toggleDay = useCallback(
276→    (day: string) => {
277→      setSelectedDays((prev) =>
278→        prev.includes(day) ? prev.filter((d) => d !== day) : [...prev, day],
279→      );
280→    },
281→    [],
282→  );
283→
284→  const zoneOptions = [
285→    { label: "All zones", value: "" },
286→    ...zones.map((z) => ({ label: z, value: z })),
287→  ];
288→
289→  const tableRows = (rules as Rule[]).map((rule) => [
290→    <InlineStack gap="200" blockAlign="center" key={`name-${rule.id}`}>
291→      <Text as="span" fontWeight="bold">
292→        {rule.name}
293→      </Text>
294→      <Badge tone={rule.isActive ? "success" : undefined}>
295→        {rule.isActive ? "Active" : "Inactive"}
296→      </Badge>
297→    </InlineStack>,
298→    rule.zone || "All",
299→    rule.deliveryFee != null ? `$${rule.deliveryFee.toFixed(2)}` : "Free",
300→    rule.minOrderAmount != null ? `$${rule.minOrderAmount.toFixed(2)}` : "—",
301→    rule.estimatedDays || "—",
302→    rule.daysOfWeek || "All days",
303→    <InlineStack gap="200" key={`actions-${rule.id}`}>
304→      <Tooltip content={rule.isActive ? "Click to deactivate" : "Click to activate"}>
305→        <Button
306→          variant="plain"
307→          tone={rule.isActive ? "success" : undefined}
308→          onClick={() => handleToggle(rule.id, rule.isActive)}
309→          accessibilityLabel={rule.isActive ? "Deactivate rule" : "Activate rule"}
310→        >
311→          {rule.isActive ? "Active" : "Inactive"}
312→        </Button>
313→      </Tooltip>
314→      <Tooltip content="Edit rule">
315→        <Button
316→          size="slim"
317→          variant="tertiary"
318→          onClick={() => openEdit(rule)}
319→          icon={EditIcon}
320→          accessibilityLabel="Edit"
321→        />
322→      </Tooltip>
323→      <Tooltip content="Delete rule">
324→        <Button
325→          size="slim"
326→          variant="tertiary"
327→          tone="critical"
328→          onClick={() => handleDelete(rule.id)}
329→          icon={DeleteIcon}
330→          accessibilityLabel="Delete"
331→        />
332→      </Tooltip>
333→    </InlineStack>,
334→  ]);
335→
336→  return (
337→    <Page
338→      title="Delivery Rules"
339→      subtitle="Configure delivery fees, minimums, schedules, and conditions per zone"
340→      backAction={{ onAction: () => navigate("/app") }}
341→      primaryAction={{
342→        content: "Add Rule",
343→        icon: PlusIcon,
344→        onAction: openCreate,
345→      }}
346→    >
347→      <Box paddingBlockEnd="1600">
348→      <Layout>
349→        <Layout.Section>
350→          <Card padding="0">
351→            {(rules as Rule[]).length === 0 ? (
352→              <EmptyState
353→                heading="No delivery rules yet"
354→                image="https://cdn.shopify.com/s/files/1/0262/4071/2726/files/emptystate-files.png"
355→                action={{
356→                  content: "Create your first rule",
357→                  onAction: openCreate,
358→                }}
359→              >
360→                <p>
361→                  Delivery rules let you set fees, minimum order amounts,
362→                  estimated delivery times, and delivery schedules for different
363→                  zones. Rules are evaluated by priority order.
364→                </p>
365→              </EmptyState>
366→            ) : (
367→              <DataTable
368→                columnContentTypes={[
369→                  "text",
370→                  "text",
371→                  "text",
372→                  "text",
373→                  "text",
374→                  "text",
375→                  "text",
376→                ]}
377→                headings={[
378→                  "Rule Name",
379→                  "Zone",
380→                  "Delivery Fee",
381→                  "Min. Order",
382→                  "ETA",
383→                  "Days",
384→                  "Actions",
385→                ]}
386→                rows={tableRows}
387→                hoverable
388→              />
389→            )}
390→          </Card>
391→        </Layout.Section>
392→      </Layout>
393→      </Box>
394→
395→      {/* Create / Edit Modal */}
396→      <Modal
397→        open={modalOpen}
398→        onClose={() => {
399→          setModalOpen(false);
400→          resetForm();
401→        }}
402→        title={editingRule ? "Edit Delivery Rule" : "Create Delivery Rule"}
403→        primaryAction={{
404→          content: editingRule ? "Save Changes" : "Create Rule",
405→          onAction: handleSave,
406→        }}
407→        secondaryActions={[
408→          {
409→            content: "Cancel",
410→            onAction: () => {
411→              setModalOpen(false);
412→              resetForm();
413→            },
414→          },
415→        ]}
416→      >
417→        <Modal.Section>
418→          <BlockStack gap="400">
419→            {actionError && <Banner tone="critical">{actionError}</Banner>}
420→
421→            <TextField
422→              label="Rule Name"
423→              value={name}
424→              onChange={setName}
425→              placeholder="e.g. Manhattan Standard Delivery"
426→              autoComplete="off"
427→              helpText="A descriptive name for this delivery rule."
428→            />
429→
430→            <InlineStack gap="300">
431→              <div style={{ flex: 1 }}>
432→                <Select
433→                  label="Zone"
434→                  options={zoneOptions}
435→                  value={zone}
436→                  onChange={setZone}
437→                  helpText="Apply this rule to a specific zone, or all zones."
438→                />
439→              </div>
440→              <div style={{ flex: 1 }}>
441→                <TextField
442→                  label="Priority"
443→                  type="number"
444→                  value={priority}
445→                  onChange={setPriority}
446→                  autoComplete="off"
447→                  helpText="Lower number = higher priority."
448→                />
449→              </div>
450→            </InlineStack>
451→
452→            <TextField
453→              label="Specific Zip Codes (optional)"
