455→              onChange={setZipCodes}
456→              placeholder="10001, 10002, 10003"
457→              autoComplete="off"
458→              helpText="Comma-separated zip codes. Leave empty to apply to all zip codes in the zone."
459→            />
460→
461→            <Divider />
462→            <Text as="h3" variant="headingSm">
463→              Pricing
464→            </Text>
465→
466→            <InlineStack gap="300">
467→              <div style={{ flex: 1 }}>
468→                <TextField
469→                  label="Delivery Fee ($)"
470→                  type="number"
471→                  value={deliveryFee}
472→                  onChange={setDeliveryFee}
473→                  placeholder="0.00"
474→                  autoComplete="off"
475→                  helpText="Leave empty for free delivery."
476→                />
477→              </div>
478→              <div style={{ flex: 1 }}>
479→                <TextField
480→                  label="Min. Order Amount ($)"
481→                  type="number"
482→                  value={minOrderAmount}
483→                  onChange={setMinOrderAmount}
484→                  placeholder="0.00"
485→                  autoComplete="off"
486→                  helpText="Minimum order to qualify for delivery."
487→                />
