489→            </InlineStack>
490→
491→            <TextField
492→              label="Free Shipping Above ($)"
493→              type="number"
494→              value={freeShippingAbove}
495→              onChange={setFreeShippingAbove}
496→              placeholder="e.g. 50.00"
497→              autoComplete="off"
498→              helpText="Waive the delivery fee for orders above this amount."
499→            />
500→
501→            <Divider />
502→            <Text as="h3" variant="headingSm">
503→              Schedule
504→            </Text>
505→
506→            <InlineStack gap="300">
507→              <div style={{ flex: 1 }}>
508→                <TextField
509→                  label="Estimated Delivery"
510→                  value={estimatedDays}
511→                  onChange={setEstimatedDays}
512→                  placeholder="e.g. 2-3 days"
513→                  autoComplete="off"
514→                />
515→              </div>
516→              <div style={{ flex: 1 }}>
517→                <TextField
518→                  label="Order Cutoff Time"
519→                  value={cutoffTime}
520→                  onChange={setCutoffTime}
521→                  placeholder="e.g. 14:00"
