 34→  SearchIcon,
 35→  DeleteIcon,
 36→  PlusIcon,
 37→  EmailIcon,
 38→} from "@shopify/polaris-icons";
 39→
 40→const PAGE_SIZE = 10;
 41→
 42→export const loader = async ({ request }: LoaderFunctionArgs) => {
 43→  const { session } = await authenticate.admin(request);
 44→  const shop = session.shop;
 45→
 46→  const entries = await db.waitlistEntry.findMany({
 47→    where: { shop },
 48→    orderBy: { createdAt: "desc" },
 49→  });
 50→
 51→  const stats = {
 52→    total: entries.length,
 53→    waiting: entries.filter((e) => e.status === "waiting").length,
 54→    notified: entries.filter((e) => e.status === "notified").length,
 55→    converted: entries.filter((e) => e.status === "converted").length,
 56→    uniqueZips: [...new Set(entries.map((e) => e.zipCode))].length,
 57→  };
 58→
 59→  return { entries, stats };
 60→};
 61→
 62→export const action = async ({ request }: ActionFunctionArgs) => {
 63→  const { session } = await authenticate.admin(request);
 64→  const shop = session.shop;
 65→  const formData = await request.formData();
 66→  const intent = formData.get("intent");
 67→
 68→  if (intent === "add") {
 69→    const email = String(formData.get("email") || "").trim().toLowerCase();
 70→    const zipCode = String(formData.get("zipCode") || "")
 71→      .trim()
 72→      .toUpperCase();
 73→    const note = String(formData.get("note") || "").trim() || null;
 74→
 75→    if (!email || !zipCode) return { error: "Email and zip code are required." };
 76→
 77→    try {
 78→      await db.waitlistEntry.create({
 79→        data: { shop, email, zipCode, note },
 80→      });
 81→      return { success: true, action: "added" };
 82→    } catch {
 83→      return { error: "This email is already on the waitlist for this zip code." };
 84→    }
 85→  }
 86→
 87→  if (intent === "delete") {
 88→    const id = String(formData.get("id"));
 89→    await db.waitlistEntry.delete({ where: { id } });
 90→    return { success: true, action: "deleted" };
 91→  }
 92→
 93→  if (intent === "update-status") {
 94→    const id = String(formData.get("id"));
 95→    const status = String(formData.get("status"));
 96→    await db.waitlistEntry.update({ where: { id }, data: { status } });
 97→    return { success: true, action: "updated" };
 98→  }
 99→
100→  if (intent === "bulk-notify") {
101→    const zipCode = String(formData.get("zipCode") || "")
102→      .trim()
103→      .toUpperCase();
104→    if (!zipCode) return { error: "Zip code is required." };
105→
106→    const updated = await db.waitlistEntry.updateMany({
107→      where: { shop, zipCode, status: "waiting" },
108→      data: { status: "notified" },
109→    });
110→
111→    return {
112→      success: true,
113→      action: "bulk-notify",
114→      count: updated.count,
115→      zipCode,
116→    };
117→  }
118→
119→  if (intent === "notify-zip") {
120→    const zipCode = String(formData.get("zipCode") || "").trim().toUpperCase();
121→    if (!zipCode) return { error: "No ZIP code specified." };
122→
123→    const entries = await db.waitlistEntry.findMany({
124→      where: { shop, zipCode, status: "waiting" },
125→      select: { id: true, email: true },
126→    });
127→
128→    if (entries.length === 0) {
129→      return { action: "notify-zip", zipCode, emails: [] as string[], count: 0 };
130→    }
131→
132→    await db.waitlistEntry.updateMany({
133→      where: { shop, zipCode, status: "waiting" },
134→      data: { status: "notified" },
135→    });
136→
137→    const emails = entries.map((e) => e.email);
138→    return { action: "notify-zip", zipCode, emails, count: emails.length };
139→  }
140→
141→  if (intent === "delete-all-notified") {
142→    const deleted = await db.waitlistEntry.deleteMany({
143→      where: { shop, status: "notified" },
144→    });
145→    return { success: true, action: "deleted-notified", count: deleted.count };
146→  }
147→
148→  return null;
149→};
