  3→ *
  4→ * Called from the theme app extension block when a zip code check fails and
  5→ * the merchant has enabled the waitlist feature.
  6→ *
  7→ * POST /api/waitlist
  8→ * Body: { shop: string, zip: string, email: string }
  9→ *
 10→ * Response:
 11→ *   200 { success: true, message: "..." }
 12→ *   400 { error: "..." }
 13→ *   500 { error: "..." }
 14→ */
 15→import type { ActionFunctionArgs, LoaderFunctionArgs } from "react-router";
 16→import db from "../db.server";
 17→
 18→/**
 19→ * Normalize postal/zip code for multi-format international support.
 20→ * Handles: US ZIP+4, UK postcodes, Indian pincodes, Australian postcodes, Canadian postal codes.
 21→ */
 22→function normalizeZipCode(raw: string): string {
 23→  let z = raw.trim().toUpperCase();
 24→  z = z.replace(/\s+/g, "");        // collapse all internal spaces (UK: SW1A 2AA → SW1A2AA)
 25→  z = z.replace(/-\d{4}$/, "");     // strip US ZIP+4 suffix (90210-1234 → 90210)
 26→  return z;
 27→}
 28→
 29→const CORS_HEADERS = {
 30→  "Access-Control-Allow-Origin": "*",
 31→  "Access-Control-Allow-Methods": "POST, OPTIONS",
 32→  "Access-Control-Allow-Headers": "Content-Type",
 33→  "Content-Type": "application/json",
 34→};
 35→
 36→// Handle CORS preflight
 37→export const loader = async ({ request }: LoaderFunctionArgs) => {
 38→  if (request.method === "OPTIONS") {
 39→    return new Response(null, { status: 204, headers: CORS_HEADERS });
 40→  }
 41→  return new Response(JSON.stringify({ error: "Method not allowed" }), {
 42→    status: 405,
 43→    headers: CORS_HEADERS,
 44→  });
 45→};
 46→
 47→export const action = async ({ request }: ActionFunctionArgs) => {
 48→  if (request.method === "OPTIONS") {
 49→    return new Response(null, { status: 204, headers: CORS_HEADERS });
 50→  }
 51→
 52→  if (request.method !== "POST") {
 53→    return new Response(JSON.stringify({ error: "Method not allowed" }), {
 54→      status: 405,
 55→      headers: CORS_HEADERS,
 56→    });
 57→  }
 58→
 59→  let shop: string | null = null;
 60→  let zip: string | null = null;
 61→  let email: string | null = null;
 62→
 63→  try {
 64→    const body = await request.json();
 65→    shop = body?.shop ?? null;
 66→    zip = body?.zip ?? null;
 67→    email = body?.email ?? null;
 68→  } catch {
 69→    return new Response(JSON.stringify({ error: "Invalid JSON body" }), {
 70→      status: 400,
 71→      headers: CORS_HEADERS,
 72→    });
 73→  }
 74→
 75→  if (!shop || !zip || !email) {
 76→    return new Response(
 77→      JSON.stringify({ error: "Missing required fields: shop, zip, email" }),
 78→      { status: 400, headers: CORS_HEADERS },
 79→    );
 80→  }
 81→
 82→  // Validate shop is a real myshopify.com domain (prevents cross-shop enumeration)
 83→  if (!/^[a-zA-Z0-9][a-zA-Z0-9-]*\.myshopify\.com$/.test(shop) || shop.length > 100) {
 84→    return new Response(
 85→      JSON.stringify({ error: "Invalid shop parameter" }),
 86→      { status: 400, headers: CORS_HEADERS },
 87→    );
 88→  }
 89→
 90→  // Enforce input length limits to prevent abuse
 91→  if (zip.length > 20 || email.length > 254) {
 92→    return new Response(
 93→      JSON.stringify({ error: "Invalid input" }),
 94→      { status: 400, headers: CORS_HEADERS },
 95→    );
 96→  }
 97→
 98→  if (!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)) {
 99→    return new Response(
100→      JSON.stringify({ error: "Invalid email address" }),
101→      { status: 400, headers: CORS_HEADERS },
102→    );
103→  }
104→
105→  try {
106→    await db.waitlistEntry.upsert({
107→      where: {
108→        shop_email_zipCode: {
109→          shop,
110→          email,
111→          zipCode: normalizeZipCode(zip),
112→        },
113→      },
114→      create: {
115→        shop,
116→        email,
117→        zipCode: normalizeZipCode(zip),
118→        status: "waiting",
119→      },
120→      update: {
121→        status: "waiting",
122→      },
123→    });
124→
125→    return new Response(
126→      JSON.stringify({
127→        success: true,
128→        message: "You've been added to the waitlist!",
129→      }),
130→      { status: 200, headers: CORS_HEADERS },
131→    );
132→  } catch {
133→    return new Response(
134→      JSON.stringify({ error: "Failed to join waitlist. Please try again." }),
135→      { status: 500, headers: CORS_HEADERS },
136→    );
137→  }
138→};
