336→// ─── Page ─────────────────────────────────────────────────────────────────────
337→
338→export default function PricingPage() {
339→  const { subscription } = useLoaderData<typeof loader>();
340→  const fetcher = useFetcher<typeof action>();
341→  const shopify = useAppBridge();
342→
343→  const [isAnnual, setIsAnnual] = useState(
344→    subscription.billingInterval === "annual",
345→  );
346→  const [loadingPlan, setLoadingPlan] = useState<string | null>(null);
347→  const [cancelModalOpen, setCancelModalOpen] = useState(false);
348→
349→  const data = fetcher.data;
350→  const isFetching = fetcher.state !== "idle";
351→
352→  // Redirect to Shopify billing confirmation page
353→  useEffect(() => {
354→    if (data && "confirmationUrl" in data && data.confirmationUrl) {
355→      window.open(data.confirmationUrl as string, "_top");
356→    }
357→  }, [data]);
358→
359→  // Toast notifications + clear loading state
360→  useEffect(() => {
361→    if (!isFetching) setLoadingPlan(null);
362→    if (data && "message" in data && data.message) {
363→      shopify.toast.show(data.message as string);
364→    }
365→    if (data && "error" in data && data.error) {
366→      shopify.toast.show(data.error as string, { isError: true });
367→    }
368→  }, [data, isFetching, shopify]);
369→
370→  const handleSubscribe = useCallback(
371→    (planName: string) => {
372→      setLoadingPlan(planName);
373→      const fd = new FormData();
374→      fd.set("intent", "subscribe");
375→      fd.set("plan", planName);
376→      fetcher.submit(fd, { method: "POST" });
377→    },
378→    [fetcher],
379→  );
380→
381→  const handleConfirmCancel = useCallback(() => {
382→    setCancelModalOpen(false);
383→    setLoadingPlan("cancel");
384→    const fd = new FormData();
385→    fd.set("intent", "cancel");
386→    fetcher.submit(fd, { method: "POST" });
387→  }, [fetcher]);
388→
389→  const currentTier = subscription.planTier;
390→  const currentPlanName =
391→    PLANS_DATA[currentTier as keyof typeof PLANS_DATA]?.name ?? "Free";
392→
393→  return (
394→    <Page
395→      title="Pricing"
396→      subtitle="Choose the plan that's right for your store"
397→      backAction={{ url: "/app" }}
398→    >
399→      <Box paddingBlockEnd="1600">
400→      <Layout>
401→        <Layout.Section>
402→          <BlockStack gap="600">
403→
404→            {/* Current plan status */}
405→            {currentTier === "free" ? (
406→              <Banner
407→                tone="info"
408→                title="You're on the Free plan"
409→                action={{
410→                  content: "Upgrade to Pro",
411→                  onAction: () => {
412→                    const plan = isAnnual
413→                      ? PLANS_DATA.pro.shopifyPlanAnnual
414→                      : PLANS_DATA.pro.shopifyPlanMonthly;
415→                    if (plan) handleSubscribe(plan);
416→                  },
417→                }}
418→              >
419→                <Text as="p" variant="bodyMd">
420→                  You have up to 25 allowed zip codes and basic widget access.
421→                  Upgrade to unlock unlimited zip codes, blocked areas, delivery
422→                  rules, and more.
423→                </Text>
424→              </Banner>
425→            ) : (
426→              <Banner tone="success" title={`You're on the ${currentPlanName} plan`}>
427→                <InlineStack gap="200" blockAlign="center">
428→                  <Badge tone="success">Active</Badge>
429→                  <Text as="p" variant="bodyMd">
430→                    {currentTier === "ultimate"
431→                      ? "You have full access to all features including VIP support and API access."
432→                      : "You have unlimited zip codes, blocked areas, delivery rules, and more."}
433→                  </Text>
434→                </InlineStack>
435→              </Banner>
436→            )}
437→
438→            {/* Action feedback banners */}
439→            {data && "error" in data && data.error && (
440→              <Banner tone="critical">{String(data.error)}</Banner>
441→            )}
442→            {data && "success" in data && data.success && (
443→              <Banner tone="success">
444→                {data && "message" in data
445→                  ? String(data.message)
446→                  : "Plan updated successfully."}
447→              </Banner>
448→            )}
449→
450→            {/* Billing toggle — centred, fully Polaris */}
451→            <BlockStack gap="200" inlineAlign="center">
452→              <ButtonGroup variant="segmented">
453→                <Button
454→                  pressed={!isAnnual}
455→                  onClick={() => setIsAnnual(false)}
456→                >
457→                  Monthly
458→                </Button>
459→                <Button
460→                  pressed={isAnnual}
461→                  onClick={() => setIsAnnual(true)}
462→                >
463→                  Annual · Save 20%
464→                </Button>
465→              </ButtonGroup>
466→              {isAnnual && (
467→                <Badge tone="success">You save up to 36% per year</Badge>
468→              )}
469→            </BlockStack>
470→
471→            {/* Plan cards */}
472→            <InlineGrid columns={{ xs: 1, sm: 1, md: 3 }} gap="400">
473→              {(
474→                Object.values(
475→                  PLANS_DATA,
476→                ) as (typeof PLANS_DATA)[keyof typeof PLANS_DATA][]
477→              ).map((plan) => (
478→                <PlanCard
479→                  key={plan.id}
480→                  plan={plan}
481→                  isAnnual={isAnnual}
482→                  currentTier={currentTier}
483→                  onSubscribe={handleSubscribe}
484→                  onRequestCancel={() => setCancelModalOpen(true)}
485→                  loadingPlan={loadingPlan}
486→                />
487→              ))}
488→            </InlineGrid>
489→
490→            {/* Trial footnote */}
491→            {currentTier === "free" && (
492→              <Text
493→                as="p"
494→                variant="bodySm"
495→                tone="subdued"
496→                alignment="center"
497→              >
498→                All paid plans include a 14-day free trial. No credit card
499→                charged until the trial ends.
500→              </Text>
501→            )}
502→
503→
504→          </BlockStack>
505→        </Layout.Section>
506→      </Layout>
507→      </Box>
508→
509→      {/* Downgrade confirmation modal */}
510→      <Modal
511→        open={cancelModalOpen}
512→        onClose={() => setCancelModalOpen(false)}
513→        title="Downgrade to Free plan?"
514→        primaryAction={{
515→          content: "Yes, downgrade",
516→          destructive: true,
517→          onAction: handleConfirmCancel,
518→          loading: loadingPlan === "cancel",
519→        }}
520→        secondaryActions={[
521→          {
522→            content: "Keep current plan",
523→            onAction: () => setCancelModalOpen(false),
524→          },
525→        ]}
526→      >
527→        <Modal.Section>
528→          <BlockStack gap="400">
529→            <Text as="p" variant="bodyMd">
530→              Downgrading to Free will immediately remove access to:
531→            </Text>
532→            <BlockStack gap="200">
533→              {[
534→                "Unlimited zip codes — limited to 25",
535→                "Blocked zip codes",
536→                "Delivery zones, ETAs, and rules",
537→                "Bulk CSV import & export",
538→                "Customer waitlist",
539→              ].map((item) => (
540→                <InlineStack key={item} gap="200" blockAlign="start" wrap={false}>
541→                  <Text as="span" variant="bodyMd" tone="subdued">·</Text>
542→                  <Text as="p" variant="bodyMd">{item}</Text>
543→                </InlineStack>
544→              ))}
545→            </BlockStack>
546→            <Banner tone="warning">
547→              <Text as="p" variant="bodyMd">
548→                Zip codes over the 25-entry limit will remain saved but become inactive until you upgrade again.
549→              </Text>
550→            </Banner>
551→          </BlockStack>
552→        </Modal.Section>
553→      </Modal>
554→    </Page>
555→  );
556→}
